-- 0032_dashboard_system_seed.sql seeded "voisinage-elements"'s three panels
-- pointing at architecture-neo4j (Cypher). Following the precedent of the
-- prior backfills in this series, this migration points the dashboard's
-- latest revision (2) at the native Postgres datasource: "graphe-voisinage"
-- is a fixed 1-hop neighborhood (no recursion needed); "proprietes" and
-- "relations" list an element's element_properties and relationships as
-- table rows, computed as a correlated subquery anchored on the selected
-- element so a nonexistent element id yields zero rows, the same shape
-- Cypher's required MATCH produces. "relations" reuses the same inline
-- ArchiMate-layer CASE expression as
-- 0037_rapports_application_datasource_postgres.sql and
-- 0038_rapports_architecture_datasource_postgres.sql for its "Couche"
-- column.
UPDATE "dashboard_revisions" AS dr
SET "definition" = $def$
{"id": "voisinage-elements", "title": "Voisinage des éléments", "description": "Explorez les relations directes de l’élément sélectionné.", "category": "Éléments", "schemaVersion": 2, "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true, "selector": {"source": "model-elements", "elementTypes": ["Stakeholder", "Driver", "Assessment", "Goal", "Outcome", "Principle", "Requirement", "Constraint", "Meaning", "Value", "Resource", "Capability", "CourseOfAction", "ValueStream", "BusinessActor", "BusinessRole", "BusinessCollaboration", "BusinessInterface", "BusinessProcess", "BusinessFunction", "BusinessInteraction", "BusinessEvent", "BusinessService", "BusinessObject", "Contract", "Representation", "Product", "ApplicationComponent", "ApplicationCollaboration", "ApplicationInterface", "ApplicationFunction", "ApplicationInteraction", "ApplicationProcess", "ApplicationEvent", "ApplicationService", "DataObject", "Node", "Device", "SystemSoftware", "TechnologyCollaboration", "TechnologyInterface", "Path", "CommunicationNetwork", "TechnologyFunction", "TechnologyProcess", "TechnologyInteraction", "TechnologyEvent", "TechnologyService", "Artifact", "Equipment", "Facility", "DistributionNetwork", "Material", "WorkPackage", "Deliverable", "ImplementationEvent", "Plateau", "Gap", "Location", "Grouping"]}}], "panels": [{"id": "graphe-voisinage", "panel": {"title": "Voisinage de l’élément", "description": "Relations directes de l’élément sélectionné, dans les deux sens.", "resultType": "graph", "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true}], "visualization": {"type": "graph"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT\n  (\n    SELECT array_agg(DISTINCT node_id) FROM (\n      SELECT e.uuid AS node_id\n      UNION\n      SELECT node_id FROM (\n        SELECT ne.uuid AS node_id\n        FROM relationships r\n        JOIN workspaces rw ON rw.id = r.workspace_id\n        JOIN elements ne ON ne.uuid = CASE WHEN r.source_uuid = e.uuid THEN r.target_uuid ELSE r.source_uuid END\n        JOIN workspaces nw ON nw.id = ne.workspace_id\n        WHERE (r.source_uuid = e.uuid OR r.target_uuid = e.uuid)\n          AND rw.organization_id = $organizationId\n          AND nw.organization_id = $organizationId\n          AND r.type IN ('Composition', 'Aggregation', 'Assignment', 'Realization', 'Serving', 'Access', 'Influence', 'Triggering', 'Flow', 'Specialization', 'Association')\n        ORDER BY ne.uuid\n        LIMIT 100\n      ) neighbors\n    ) all_nodes\n  ) AS \"nodeIds\",\n  e.uuid AS \"emphasizedId\"\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId AND e.uuid = $elementId"}}, "layout": {"x": 0, "y": 0, "width": 12, "height": 8}, "parameterBindings": {"elementId": {"source": "dashboard", "parameter": "elementId"}}}, {"id": "proprietes", "panel": {"title": "Propriétés", "description": "Propriétés ArchiMate de l’élément sélectionné.", "resultType": "table", "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true}], "visualization": {"type": "table"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT COALESCE(\n  (\n    SELECT jsonb_agg(jsonb_build_object('Nom', pd.name, 'Valeur', ep.value) ORDER BY pd.name)\n    FROM element_properties ep\n    JOIN property_definitions pd ON pd.uuid = ep.property_def_uuid AND pd.workspace_id = e.workspace_id\n    WHERE ep.element_id = e.id\n  ),\n  '[]'::jsonb\n) AS rows\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId AND e.uuid = $elementId"}}, "layout": {"x": 0, "y": 8, "width": 12, "height": 5}, "parameterBindings": {"elementId": {"source": "dashboard", "parameter": "elementId"}}}, {"id": "relations", "panel": {"title": "Relations", "description": "Relations entrantes et sortantes de l’élément sélectionné.", "resultType": "table", "parameters": [{"name": "elementId", "label": "Élément", "type": "string", "required": true}], "visualization": {"columnOrder": ["Direction", "Relation", "Élément", "Type", "Couche"], "type": "table"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT COALESCE(\n  (\n    SELECT jsonb_agg(jsonb_build_object(\n      'Direction', CASE WHEN r.source_uuid = e.uuid THEN 'Sortante' ELSE 'Entrante' END,\n      'Relation', r.type,\n      'Élément', oe.name,\n      'Type', oe.type,\n      'Couche', (CASE\n    WHEN oe.type LIKE 'Business%' OR oe.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN oe.type LIKE 'Application%' OR oe.type = 'DataObject' THEN 'Application'\n    WHEN oe.type LIKE 'Technology%' OR oe.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN oe.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN oe.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN oe.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN oe.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END)\n    ))\n    FROM relationships r\n    JOIN workspaces rw ON rw.id = r.workspace_id\n    JOIN elements oe ON oe.uuid = CASE WHEN r.source_uuid = e.uuid THEN r.target_uuid ELSE r.source_uuid END\n    JOIN workspaces ow ON ow.id = oe.workspace_id\n    WHERE rw.organization_id = $organizationId\n      AND ow.organization_id = $organizationId\n      AND (r.source_uuid = e.uuid OR r.target_uuid = e.uuid)\n  ),\n  '[]'::jsonb\n) AS rows\nFROM elements e\nJOIN workspaces w ON w.id = e.workspace_id\nWHERE w.organization_id = $organizationId AND e.uuid = $elementId"}}, "layout": {"x": 0, "y": 8, "width": 12, "height": 5}, "parameterBindings": {"elementId": {"source": "dashboard", "parameter": "elementId"}}}], "tabGroups": [{"id": "details-element", "tabs": [{"id": "proprietes", "title": "Propriétés", "panelIds": ["proprietes"]}, {"id": "relations", "title": "Relations", "panelIds": ["relations"]}]}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-17T03:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "system"}
$def$::jsonb
FROM "dashboards" AS dd
WHERE dr."dashboard_id" = dd."id"
  AND dd."dashboard_id" = 'voisinage-elements'
  AND dd."workspace_id" IS NULL
  AND dr."revision" = dd."latest_revision";
